begin;
\ir batch_2_fixture.sql
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='sales_user'),true);
set local role authenticated;
select pg_temp.denied(format('update public.products set selling_price=99 where id=%L',(select id from batch2_ids where key='product')));
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='inventory_user'),true);
select pg_temp.denied(format('insert into public.products(business_id,name,selling_price) values(%L,''Forged'',0)',(select id from batch2_ids where key='business')));
select pg_temp.denied(format('update public.products set selling_price=10 where id=%L',(select id from batch2_ids where key='product')));
select pg_temp.denied(format('insert into public.products(id,business_id,name,selling_price) values(%L,%L,''Upsert'',10) on conflict(id) do update set selling_price=excluded.selling_price',(select id from batch2_ids where key='product'),(select id from batch2_ids where key='business')));
select pg_temp.denied(format('update public.products set selling_price=7 where business_id=%L',(select id from batch2_ids where key='business')));
select pg_temp.denied(format('select public.set_trexven_employee_permission(%L,''override_price'',true)',(select id from batch2_ids where key='inventory')));
select pg_temp.denied(format('insert into public.products(business_id,name,cost_price) values(%L,''Cost bypass'',50)',(select id from batch2_ids where key='business')));
insert into public.products(business_id,name) values((select id from batch2_ids where key='business'),'Synthetic pending');
select pg_temp.denied(format('update public.products set quantity=999 where id=%L',(select id from batch2_ids where key='product')));
select pg_temp.assert_true((select selling_price is null and active=false and is_active=false from public.products where name='Synthetic pending' and business_id=(select id from batch2_ids where key='business')),'unpriced product remains pending');
select pg_temp.denied(format('insert into public.products(business_id,name) values(%L,''Other business'')',(select id from batch2_ids where key='other_business')));
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
insert into public.products(business_id,name,selling_price,quantity) values((select id from batch2_ids where key='business'),'Synthetic free',0,5);
select pg_temp.assert_true((select selling_price=0 and is_active from public.products where name='Synthetic free' and business_id=(select id from batch2_ids where key='business')),'explicit owner zero is preserved');
select pg_temp.fails(format('select public.record_trexven_sale(%L,%L,1,0)',(select id from batch2_ids where key='business'),(select id from public.products where name='Synthetic pending' and business_id=(select id from batch2_ids where key='business'))));
select public.set_trexven_employee_permission((select id from batch2_ids where key='manager'),'override_price',true);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
update public.products set selling_price=12 where id=(select id from batch2_ids where key='product');
select pg_temp.assert_true((select selling_price=12 from public.products where id=(select id from batch2_ids where key='product')),'explicit manager price edit succeeds');
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='owner'),true);
select public.set_trexven_employee_permission((select id from batch2_ids where key='manager'),'override_price',false);
select set_config('request.jwt.claim.sub',(select id::text from batch2_ids where key='manager_user'),true);
select pg_temp.denied(format('update public.products set selling_price=13 where id=%L',(select id from batch2_ids where key='product')));
reset role;
select 'Price security assertions completed (isolated runtime required)' as result;
rollback;
